/* ── types ─────────────────────────────────────────────── */

/*
 * Named f32 tensors (weights, trainer params): iterate with
 * `rlx_tensor_map_len` / `rlx_tensor_map_get`, free with `rlx_tensor_map_free`.
 */
typedef struct RlxTensorMap RlxTensorMap;

/*
 * A graph, or the hole left after something consumed it (`rlx_session_compile`,
 * a body-graph argument).
 */
typedef struct RlxGraph RlxGraph;

/*
 * A graph split into parts that run in order.
 */
typedef struct RlxPartition RlxPartition;

/*
 * A device and precision to compile graphs for.
 */
typedef struct RlxSession RlxSession;

/*
 * A graph compiled for one device.
 */
typedef struct RlxCompiled RlxCompiled;

/*
 * The outputs of a run: one f32 buffer per graph output.
 */
typedef struct RlxOutputs RlxOutputs;

/*
 * The outputs of a typed run: bytes plus a dtype name per output.
 */
typedef struct RlxTypedOutputs RlxTypedOutputs;

/*
 * A session that picks the device per graph from a device policy.
 */
typedef struct RlxFlexibleSession RlxFlexibleSession;

/*
 * One graph compiled lazily per device (`GraphDevices`).
 */
typedef struct RlxRunner RlxRunner;

/*
 * A graph routed to a device per run, with fallback (`DeviceRouter`).
 */
typedef struct RlxRouter RlxRouter;

/*
 * An open, memory-mapped GGUF file.
 */
typedef struct RlxGguf RlxGguf;

/*
 * Tensors queued for `rlx_gguf_writer_write`.
 */
typedef struct RlxGgufWriter RlxGgufWriter;

/*
 * One of rlx-optim's algorithms over arrays the caller owns.
 */
typedef struct RlxOptimizer RlxOptimizer;

/*
 * Differentiate-once / compile-once training over a scalar-loss graph.
 */
typedef struct RlxTrainer RlxTrainer;

/*
 * One step's inputs, filled by an `RlxBatchFn` with `rlx_batch_set`.
 */
typedef struct RlxBatch RlxBatch;

/*
 * A tokenizer plus one streaming decode's state.
 */
typedef struct RlxTokenizer RlxTokenizer;

/*
 * A sampler carrying its history and RNG across tokens.
 */
typedef struct RlxSampler RlxSampler;

/*
 * This process's membership in a mesh of rlx nodes.
 */
typedef struct RlxGroup RlxGroup;

/*
 * A loaded model.
 */
typedef struct RlxModel RlxModel;

/*
 * A `uint32_t` array rlx allocated; free with `rlx_u32s_free`.
 */
typedef struct RlxU32s {
    uint32_t* ptr;
    size_t len;
} RlxU32s;

/*
 * A `float` array rlx allocated; free with `rlx_f32s_free`.
 */
typedef struct RlxF32s {
    float* ptr;
    size_t len;
} RlxF32s;

/*
 * A byte array rlx allocated; free with `rlx_bytes_free`.
 */
typedef struct RlxBytes {
    uint8_t* ptr;
    size_t len;
} RlxBytes;

/*
 * Supply step `step`'s inputs into `batch`: return `1` when filled, `0` when
 * the data is exhausted, a negative value to abort the run.
 */
typedef int32_t (*RlxBatchFn)(void* user, uint64_t step, RlxBatch* batch);

/*
 * Schedule the learning rate: write `*lr` and return `1`, or return `0` to
 * keep the current one.
 */
typedef int32_t (*RlxLrFn)(void* user, uint64_t step, float* lr);

/*
 * Called after a step with its loss: return `0` to stop early, `1` to go on.
 */
typedef int32_t (*RlxStepFn)(void* user, uint64_t step, float loss);

/*
 * Success.
 */
#define RLX_OK (0)

/*
 * A wrong argument: unknown name, bad shape, wrong arity.
 */
#define RLX_ERR_TYPE (-1)

/*
 * An index or value out of range (a node id the graph does not have).
 */
#define RLX_ERR_RANGE (-2)

/*
 * Well-formed but not carried out: I/O, a backend not in this build.
 */
#define RLX_ERR_RUNTIME (-3)

/*
 * A Rust assertion inside rlx, caught at the boundary.
 */
#define RLX_ERR_PANIC (-4)

/*
 * A file that does not exist.
 */
#define RLX_ERR_NOT_FOUND (-5)

/*
 * "No node" for an optional node argument.
 */
#define RLX_NONE (0xFFFFFFFFu)


/* ── Status codes, the last-error slot, owned buffers, and the argument / result */

/*
 * The message of the last failed call on this thread (empty if none). Valid
 * until the next failing call on this thread; do not free.
 */
const char* rlx_last_error(void);

/*
 * The library version, e.g. `"0.2.18"`. Static; do not free.
 */
const char* rlx_version(void);

/*
 * Free a `uint32_t` array rlx returned.
 */
void rlx_u32s_free(RlxU32s v);

/*
 * Free a `float` array rlx returned.
 */
void rlx_f32s_free(RlxF32s v);

/*
 * Free a byte array rlx returned.
 */
void rlx_bytes_free(RlxBytes v);

/*
 * Free a `uint32_t` array through a pointer to it — for FFIs that cannot pass
 * a struct by value (Ruby's Fiddle). Same as `rlx_u32s_free(*v)`.
 */
void rlx_u32s_release(RlxU32s* v);

/*
 * Free a `float` array through a pointer to it — see `rlx_u32s_release`.
 */
void rlx_f32s_release(RlxF32s* v);

/*
 * Free a byte array through a pointer to it — see `rlx_u32s_release`.
 */
void rlx_bytes_release(RlxBytes* v);

/*
 * Free a string rlx returned.
 */
void rlx_string_free(char* s);

/*
 * How many tensors the map holds (`0` for `NULL`).
 */
size_t rlx_tensor_map_len(const RlxTensorMap* m);

/*
 * Borrow entry `i`: name and data stay valid until `rlx_tensor_map_free`.
 */
int32_t rlx_tensor_map_get(
    const RlxTensorMap* m,
    size_t i,
    const char** name,
    const float** data,
    size_t* len
);

/*
 * Free a tensor map (`NULL` is a no-op).
 */
void rlx_tensor_map_free(RlxTensorMap* m);


/* ── The graph handle. Builder functions are in `graph_ops` (generated). */

/*
 * Create an empty graph named `name`.
 */
int32_t rlx_graph_new(const char* name, RlxGraph** out);

/*
 * Free a graph handle (`NULL` is a no-op).
 */
void rlx_graph_free(RlxGraph* g);

/*
 * A deep copy — compile one, keep building on the other.
 */
int32_t rlx_graph_clone(RlxGraph* g, RlxGraph** out);

/*
 * Whether the graph was consumed (by a compile, or as a body graph).
 */
bool rlx_graph_is_consumed(RlxGraph* g);


